 auto hp=heap(D3D12_HEAP_TYPE_DEFAULT);auto d=texture(width,height,DXGI_FORMAT_D32_FLOAT,D3D12_RESOURCE_FLAG_ALLOW_DEPTH_STENCIL);D3D12_CLEAR_VALUE cv={};cv.Format=d.Format;cv.DepthStencil.Depth=1;check(device->CreateCommittedResource(&hp,D3D12_HEAP_FLAG_NONE,&d,D3D12_RESOURCE_STATE_DEPTH_WRITE,&cv,IID_PPV_ARGS(&depth)),"Depth buffer");device->CreateDepthStencilView(depth.Get(),nullptr,dsvHeap->GetCPUDescriptorHandleForHeapStart());
